package recruiter

import (
	"context"
	"errors"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrFakeStorage struct {
	storage.Client
	cancel context.CancelFunc
	writes int
}

// ReadFile explicitly honors context cancellation per the contract of a real storage.Client.
func (f *gsrFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return f.Client.ReadFile(ctx, bucket, key)
}

// WriteFile simulates a concurrent write conflict and concurrently cancels the context.
func (f *gsrFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	f.writes++
	if f.cancel != nil {
		f.cancel()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	f := &gsrFakeStorage{
		Client: storage.NewMemoryClient(),
		cancel: cancel,
	}
	s := &Store{Storage: f, Bucket: "test"}

	_, err := s.Mutate(ctx, "test-url", func(c Contact) Contact { return c })

	if err == nil {
		t.Fatal("Mutate() returned nil error, want context.Canceled")
	}
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Mutate() error = %v, want context.Canceled", err)
	}
	if f.writes >= maxWriteRetries {
		t.Fatalf("Mutate() exhausted retries (writes = %d), want early abort on context cancellation", f.writes)
	}
}

package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrFakeStorage struct {
	storage.Client
	cancel        context.CancelFunc
	writeAttempts int
}

func (f *gsrFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	// Mock a successful read to isolate testing the retry loop behavior itself
	return []byte(`{}`), "fake-etag", nil
}

func (f *gsrFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	f.writeAttempts++
	// Cancel the context synchronously before returning the mismatch to trigger the bug
	f.cancel()
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	f := &gsrFakeStorage{
		Client: storage.NewMemoryClient(),
		cancel: cancel,
	}
	s := &Store{Storage: f, Bucket: "test-bucket"}

	_, _ = s.Mutate(ctx, "profile-1", func(c Contact) Contact { return c })

	if f.writeAttempts > 1 {
		t.Fatalf("Mutate(cancelledCtx) = %d write attempts, want 1", f.writeAttempts)
	}
}

package recruiter

import (
	"context"
	"strings"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrFakeStorage struct {
	storage.Client
	cancel context.CancelFunc
	writes int
}

func (f *gsrFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return []byte(`{}`), "etag1", nil
}

func (f *gsrFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	f.writes++
	if f.cancel != nil {
		f.cancel()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	fs := &gsrFakeStorage{cancel: cancel}
	s := &Store{Storage: fs, Bucket: "test"}

	_, err := s.Mutate(ctx, "url", func(c Contact) Contact { return c })

	if fs.writes == maxWriteRetries {
		t.Fatalf("fs.writes = %v, want < %v (early abort)", fs.writes, maxWriteRetries)
	}
	if err != nil && strings.Contains(err.Error(), "giving up") {
		t.Fatalf("Mutate() err = %q, want early context cancellation error", err)
	}
}
